<?php require __DIR__.'/../app/bootstrap.php';if(!empty($_SESSION['user_id'])){header('Location:/dashboard.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=preg_replace('/\D+/','',$_POST['phone']??'');$pass=$_POST['password']??'';$code=strtoupper(trim($_POST['referral']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8||!$name){flash('error','Enter a valid name, email and password of at least 8 characters.');header('Location:/register.php');exit;}try{$pdo->beginTransaction();$referrer=null;if($code){$q=$pdo->prepare('SELECT id FROM users WHERE referral_code=?');$q->execute([$code]);$referrer=$q->fetchColumn()?:null;}$mycode='STE'.strtoupper(substr(bin2hex(random_bytes(5)),0,8));$s=$pdo->prepare('INSERT INTO users(name,email,phone,password_hash,referral_code,referred_by) VALUES(?,?,?,?,?,?)');$s->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT),$mycode,$referrer]);$uid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO wallets(user_id,balance) VALUES(?,0)')->execute([$uid]);if($referrer)$pdo->prepare('INSERT INTO referrals(referrer_id,referred_id) VALUES(?,?)')->execute([$referrer,$uid]);$pdo->commit();flash('success','Account created. You can now login.');header('Location:/login.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','Email or referral code may be invalid/already registered.');header('Location:/register.php');exit;}}require __DIR__.'/../app/layout.php';header_html('Register');?><div class="auth card"><img src="/logo.jpg" class="auth-logo"><h2>Create account</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input name="phone" placeholder="08012345678"></div><div class="field"><label>Referral code (optional)</label><input name="referral"></div><div class="field"><label>Password</label><input type="password" name="password" minlength="8" required></div><button class="btn">Register</button></form><p>Already registered? <a href="/login.php">Login</a></p></div><?php footer_html();
